import { ReactNode, FC } from 'react';

type StepsDirection = 'horizontal' | 'vertical';
type StepStatus = 'wait' | 'process' | 'finish' | 'error';
interface StepItem {
    /** 标题 */
    title: string;
    /** 描述 */
    description?: string;
    /** 自定义图标 */
    icon?: ReactNode;
    /** 状态 */
    status?: StepStatus;
}
interface StepsProps {
    /** 当前步骤（从 0 开始） */
    current: number;
    /** 步骤项 */
    items: StepItem[];
    /** 方向 */
    direction?: StepsDirection;
    /** 是否使用点状样式 */
    dot?: boolean;
    /** 步骤变化回调 */
    onChange?: (current: number) => void;
    /** 自定义类名 */
    className?: string;
}

declare const Steps: FC<StepsProps>;

export { Steps, Steps as default };
export type { StepItem, StepStatus, StepsDirection, StepsProps };
